        '<b>Nebenwinkel</b> ergänzen sich zu 180° → {0} = 180° − {1}° = <b>{2}°</b>' => ['Les <b>angles adjacents</b> sur une droite totalisent 180° → {0} = 180° − {1}° = <b>{2}°</b>', 'Gli <b>angoli adiacenti</b> su una retta sommano 180° → {0} = 180° − {1}° = <b>{2}°</b>', '<b>Adjacent angles</b> on a line add up to 180° → {0} = 180° − {1}° = <b>{2}°</b>'],
        'α und {0}° liegen sich am Schnittpunkt gegenüber → <b>Scheitelwinkel</b>.' => ['α et {0}° sont opposés au point d’intersection → <b>angles opposés par le sommet</b>.', 'α e {0}° sono opposti nel punto di intersezione → <b>angoli opposti al vertice</b>.', 'α and {0}° are opposite each other at the intersection → <b>vertically opposite angles</b>.'],
        'Scheitelwinkel sind gleich gross: α = <b>{0}°</b>' => ['Les angles opposés par le sommet sont égaux&nbsp;: α = <b>{0}°</b>', 'Gli angoli opposti al vertice sono uguali: α = <b>{0}°</b>', 'Vertically opposite angles are equal: α = <b>{0}°</b>'],
        'α und {0}° liegen nebeneinander an einer Geraden → <b>Nebenwinkel</b>.' => ['α et {0}° sont côte à côte sur une droite → <b>angles adjacents</b>.', 'α e {0}° sono uno accanto all’altro su una retta → <b>angoli adiacenti</b>.', 'α and {0}° lie next to each other on a line → <b>adjacent angles</b>.'],
        'Nebenwinkel ergänzen sich zu 180°: α = 180° − {0}° = <b>{1}°</b>' => ['Les angles adjacents sur une droite totalisent 180°&nbsp;: α = 180° − {0}° = <b>{1}°</b>', 'Gli angoli adiacenti su una retta sommano 180°: α = 180° − {0}° = <b>{1}°</b>', 'Adjacent angles on a line add up to 180°: α = 180° − {0}° = <b>{1}°</b>'],
        'Gegenüberliegende Winkel sind <b>Scheitelwinkel</b> und damit gleich gross.' => ['Les angles opposés sont des <b>angles opposés par le sommet</b>, donc égaux.', 'Gli angoli opposti sono <b>angoli opposti al vertice</b> e quindi uguali.', 'Opposite angles are <b>vertically opposite angles</b> and therefore equal.'],
