        '{0} und {1}° sind <b>Scheitelwinkel</b>: {0} = <b>{1}°</b>' => ['{0} et {1}° sont des <b>angles opposés par le sommet</b>&nbsp;: {0} = <b>{1}°</b>', '{0} e {1}° sono <b>angoli opposti al vertice</b>: {0} = <b>{1}°</b>', '{0} and {1}° are <b>vertically opposite angles</b>: {0} = <b>{1}°</b>'],
